// HasPullRequest applies the HasEdge predicate on the "pull_request" edge.
func HasPullRequest() predicate.WorkItemStateSnapshot {
	return predicate.WorkItemStateSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, PullRequestTable, PullRequestColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPullRequestWith applies the HasEdge predicate on the "pull_request" edge with a given conditions (other predicates).
func HasPullRequestWith(preds ...predicate.PullRequest) predicate.WorkItemStateSnapshot {
	return predicate.WorkItemStateSnapshot(func(s *sql.Selector) {
		step := newPullRequestStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

